import {developmentViews,developmentRequirements,developmentScene,developmentAnimated,thirlmerePhoto} from './model-glaciers3.js?v=20261023-uplands03';
export {thirlmerePhoto};
import {glacierViews2,glacierRequirements2,glacierScene2,glacierAnimated2} from './model-glaciers2.js?v=20261023-uplands03';
import {uplandViews,uplandRequirements,uplandScene,uplandAnimated} from './model-glaciers.js?v=20261023-uplands03';
import {viewsR2,requirementsR2,sceneR2,animatedR2,highForcePhoto,hydrograph} from './model-rivers2.js?v=20261023-uplands03';
export {highForcePhoto,hydrograph};
import {riverViews,riverRequirements,riverScene,riverAnimated,gaugeTable} from './model-rivers.js?v=20261023-uplands03';
export {gaugeTable};
export const isProcessView=(kind,view)=>developmentViews[kind]?developmentAnimated(kind,view):glacierViews2[kind]?glacierAnimated2(kind,view):uplandViews[kind]?uplandAnimated(kind,view):viewsR2[kind]?animatedR2(kind,view):kind.startsWith('coast-')||(kind.startsWith('river-')&&riverAnimated(kind,view));
import {views2,requirements2,scene2} from './model-coasts2.js?v=20261023-uplands03';
import {coastalViews,coastalRequirements,coastalScene} from './model-coasts.js?v=20261023-uplands03';
import {UK_PATH} from './uk-outline.js?v=20261023-geography01';
export const specimens={granite:['Granite','Igneous: interlocking coarse crystals, slow cooling at depth.'],basalt:['Basalt','Igneous: usually fine crystals, cooled more quickly near the surface.'],sandstone:['Sandstone','Sedimentary: deposited sand grains held by cement.'],chalk:['Chalk','Sedimentary: largely microscopic marine remains.'],slate:['Slate','Metamorphic: cleavage developed as existing rock changed in the solid state.'],schist:['Schist','Metamorphic: visible minerals commonly aligned during solid-state change.']};
export const requirements={...developmentRequirements,...glacierRequirements2,...uplandRequirements,...requirementsR2,...riverRequirements,...requirements2,...coastalRequirements,rocks:Object.keys(specimens),map:['dartmoor','downs','highlands'],profile:['left','right'],process:['0','1','2'],landuse:['fields','trees','town']};
export function scene(kind,selection='granite',phase=0){if(developmentViews[kind])return developmentScene(kind,selection,phase);if(glacierViews2[kind])return glacierScene2(kind,selection,phase);if(uplandViews[kind])return uplandScene(kind,selection,phase);if(viewsR2[kind])return sceneR2(kind,selection,phase);if(riverViews[kind])return riverScene(kind,selection,phase);if(views2[kind])return scene2(kind,selection,phase);if(coastalViews[kind])return coastalScene(kind,selection,phase);let text='',body='';
 if(kind==='rocks'){const key=specimens[selection]?selection:'granite';text=specimens[key].join(' — ');const sediment=['chalk','sandstone'].includes(key),meta=['slate','schist'].includes(key);body=`<path d="M90 70L310 85 350 220 120 245 65 165Z" fill="#b7c4c9" stroke="#eef0ef" stroke-width="3"/>`+(sediment?Array.from({length:6},(_,i)=>`<path d="M90 ${95+i*22}L330 ${105+i*22}" stroke="#61798c" stroke-width="5"/>`).join(''):meta?Array.from({length:10},(_,i)=>`<path d="M100 ${90+i*13}L315 ${110+i*13}" stroke="#61798c" stroke-width="3"/>`).join(''):Array.from({length:36},(_,i)=>`<circle cx="${110+i%6*35}" cy="${105+Math.floor(i/6)*22}" r="${key==='basalt'?3:7}" fill="${i%2?'#f5e5dc':'#526d80'}"/>`).join(''));}
 if(kind==='map'){text='Generalised UK outline: Natural Earth. Selected representative sites only; markers identify examples, not geological boundaries.';const sites=[['highlands','Western Highlands','Metamorphic examples',107,76,95],['dartmoor','Dartmoor','Granite — igneous',132,255,185],['downs','South Downs','Chalk — sedimentary',210,247,265]];body=`<path d="${UK_PATH}" fill="#7896a5" stroke="#b9cbd1" stroke-width="1.2"/><path d="M370 55V25l-6 10m6-10 6 10" fill="none" stroke="#eaf0f1"/><text x="365" y="75">N</text><text x="30" y="320">Generalised locator · selected rock examples</text>`+sites.map(([id,name,rock,x,y,ly])=>`<path d="M${x} ${y}L280 ${ly}" stroke="#a2b6be" stroke-width="1"/><circle cx="${x}" cy="${y}" r="${selection===id?8:5}" fill="${selection===id?'#ed8b78':'#e6edef'}"/><text x="282" y="${ly-8}" class="geo-small">${name}</text><text x="282" y="${ly+10}" class="geo-small">${rock}</text>`).join('');}
 if(kind==='profile'){const left=selection!=='right',a=left?90:60,b=left?60:90;text=`Controlled example: equal starting height100; after equal erosion time, left${a}, right${b} teaching units. These are invented values, not forecasts.`;body=`<path d="M50 80H370" stroke="#e6cebd" stroke-dasharray="6 5"/><rect x="60" y="${260-a*1.8}" width="140" height="${a*1.8}" fill="#a7bdc5"/><rect x="200" y="${260-b*1.8}" width="140" height="${b*1.8}" fill="#edb5a5"/><text x="75" y="290">Left: ${a}</text><text x="230" y="290">Right: ${b}</text><text x="65" y="45">Dashed line: equal starting height</text>`;}
 if(kind==='process'){phase=Math.max(0,Math.min(2,phase));text=['Past ice: erosion, transport and deposition reshape a valley.','After ice retreat: river erosion, transport and deposition continue.','Weathering breaks rock in place; gravity moves loose material downhill.'][phase];body=`<path d="M30 80L95 120Q210 ${phase===0?255:225} 325 120L390 80V300H30Z" fill="#8c9eaa"/><path d="M95 120Q210 245 325 120" fill="none" stroke="#d2e5ec" stroke-width="${phase===0?45:4}"/><path d="M180 220Q225 220 235 290" stroke="#a9d7e6" stroke-width="${phase===1?13:4}" fill="none"/>${phase===2?'<path d="M95 105l45 68" stroke="#ed8b78" stroke-width="7"/><text x="30" y="45">Breakdown in place → downslope movement</text>':''}<text x="40" y="330">Conceptual valley — not a named place or time scale</text>`;}
 if(kind==='landuse'){text={fields:'Agriculture: field boundaries and tracks alter the pattern of the land.',trees:'Forestry: planted blocks and cleared plots change tree cover.',town:'Settlement: buildings and roads increase the built area.'}[selection]||'Choose a land-use layer.';body='<rect x="40" y="35" width="340" height="240" fill="#78928c"/><path d="M240 35Q180 140 250 275" fill="none" stroke="#a9d7e6" stroke-width="12"/>'+(selection==='fields'?Array.from({length:6},(_,i)=>`<rect x="${55+i%3*85}" y="${55+Math.floor(i/3)*90}" width="72" height="72" fill="#bcc59a" stroke="#f8f6f2"/>`).join(''):selection==='trees'?Array.from({length:30},(_,i)=>`<path d="M${60+i%6*36} ${55+Math.floor(i/6)*36}l-9 19h18z" fill="#d2dfce"/>`).join(''):Array.from({length:16},(_,i)=>`<rect x="${65+i%4*46}" y="${65+Math.floor(i/4)*40}" width="25" height="21" fill="#f5e5dc"/>`).join('')+'<path d="M40 130H225V275" stroke="#f8f6f2" stroke-width="6" fill="none"/>');}
 return `<svg class="geo-scene" viewBox="0 0 420 355" role="img" aria-label="${text.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}"><style>.geo-scene text{font:13px sans-serif;fill:#eaf0f1}.geo-scene .geo-small{font-size:10px}</style>${body}</svg><p class="geo-caption">${text}</p>`;
}
export function controls(kind){if(developmentViews[kind])return developmentViews[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');if(glacierViews2[kind])return glacierViews2[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');if(uplandViews[kind])return uplandViews[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');if(viewsR2[kind])return viewsR2[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');if(riverViews[kind])return riverViews[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');if(views2[kind])return views2[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');if(coastalViews[kind])return coastalViews[kind].map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');const entries=kind==='rocks'?Object.entries(specimens).map(([id,v])=>[id,v[0]]):kind==='map'?[['dartmoor','Dartmoor'],['downs','South Downs'],['highlands','Western Highlands']]:kind==='profile'?[['left','Left more resistant'],['right','Right more resistant']]:kind==='process'?[['0','Past ice'],['1','River after ice'],['2','Weathering & slopes']]:[['fields','Farming'],['trees','Forestry'],['town','Settlement']];return entries.map(([id,label])=>`<button class="scene-button" data-geo-view="${id}">${label}</button>`).join('');}
